seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>')).upper()
n=len(seq)

# homopolymers
for m in re.finditer(r'(A{4,}|T{4,}|G{4,}|C{4,})', seq):
    print('homopolymer',m.group(),m.start()+1)
print('---inverted repeats (palindrome arms >=8 with spacer<=20)---')
comp=str.maketrans('ACGT','TGCA')
# search for inverted repeats: find stem length>=8
found=[]
for stem in range(14,7,-1):
    for i in range(n-stem+1):
        arm=seq[i:i+stem]
        target=arm.translate(comp)[::-1]
        for j in range(i+stem+3, min(i+stem+30, n-stem+1)):
            if seq[j:j+stem]==target:
                found.append((i+1,j+1,stem,j-i-stem))
for f in found[:30]:
    print(f)
print('total IR', len(found))
